for key, text in UPDATE.items():
    pattern = re.compile(r'^(\s*)"' + re.escape(key) + r'": ".*",\s*$', re.M)
    assert pattern.search(s), "KEY NOT FOUND: " + key
    s = pattern.sub(lambda m: m.group(1) + '"' + key + '": "' + text + '",', s, count=1)

add = "    # ---------------- Client ke naye ferfaar (pehle vs ab)\n"
for key, text in NEW.items():
    assert '"' + key + '"' not in s, "already there: " + key
    add += '    "' + key + '": "' + text + '",\n'
idx = s.rstrip().rfind("}")
s = s[:idx] + add + s[idx:]
io.open(P, "w", encoding="utf-8", newline="").write(s)
print("updated", len(UPDATE), "added", len(NEW))
